def _released_few_shot_serialization(examples: str) -> str:
    rendered: list[str] = []
    for section in examples.split("DOCUMENT TO ANALYZE:\n")[1:]:
        document, response = section.rsplit("\nRESPONSE:\n", 1)
        rendered.append(
            f"DOCUMENT TO ANALYZE:\n{document}\nRESPONSE:\n{json.loads(response)}\n\n"
        )
    return "".join(rendered)


_FEW_SHOT_EXAMPLES = _released_few_shot_serialization(_FEW_SHOT_EXAMPLES)
_EXTRACTION_TEMPLATE = (
    _EXTRACTION_TEMPLATE.replace(
        "### Entity Extraction Rules\n\n1. **Extract",
        "### Entity Extraction Rules\n\n\n1. **Extract",
    )
    .replace(
        "Do the same for each relationship.\n2. Extract",
        "Do the same for each relationship.\n\n2. Extract",
    )
    .replace(
        "relationship in the document)\n2. Extract multiple",
        "relationship in the document)\n\n2. Extract multiple",
    )
    .replace(
        "according to the criteria below\n3. Relationship types",
        "according to the criteria below\n\n3. Relationship types",
    )
)


def extraction_prompt(filename: str, content: str) -> str:
    if (
        not isinstance(filename, str)
        or not 1 <= len(filename) <= 1_000
        or any(character in filename for character in "\x00\r\n")
    ):
        raise ValueError("Invalid document filename")
    if not isinstance(content, str) or "\x00" in content:
        raise ValueError("Invalid document content")
    return (
        _EXTRACTION_TEMPLATE.replace("{{ few_shot_examples }}", _FEW_SHOT_EXAMPLES)
        .replace("{{ document_filename }}", filename)
        .replace("{{ document_content }}", content[:10_000])
    )
